# Makefile - 教案生成API项目管理

.PHONY: help install dev prod test clean docker-build docker-run docker-stop format lint type-check

# 默认目标
help:
	@echo "教案生成API - 可用命令:"
	@echo ""
	@echo "  make install      - 安装项目依赖"
	@echo "  make dev          - 启动开发服务器"
	@echo "  make prod         - 启动生产服务器（gunicorn）"
	@echo "  make test         - 运行测试套件"
	@echo "  make test-api     - 运行API测试"
	@echo "  make clean        - 清理临时文件"
	@echo ""
	@echo "  make docker-build - 构建Docker镜像"
	@echo "  make docker-run   - 运行Docker容器"
	@echo "  make docker-stop  - 停止Docker容器"
	@echo "  make docker-logs  - 查看Docker日志"
	@echo ""
	@echo "  make format       - 格式化代码（black）"
	@echo "  make lint         - 代码风格检查（flake8）"
	@echo "  make type-check   - 类型检查（mypy）"
	@echo "  make check        - 运行所有检查"

# 安装依赖
install:
	@echo "安装项目依赖..."
	pip install -r requirements.txt
	@echo "依赖安装完成!"

# 开发环境
dev:
	@echo "启动开发服务器..."
	python app.py

# 生产环境
prod:
	@echo "启动生产服务器..."
	gunicorn -k uvicorn.workers.UvicornWorker \
		-w 4 \
		-b 0.0.0.0:8000 \
		--access-logfile - \
		--error-logfile - \
		--log-level info \
		app:app

# 测试
test:
	@echo "运行测试套件..."
	pytest test_generator.py -v --cov=lesson_plan_generator --cov-report=html

test-api:
	@echo "运行API测试..."
	python test_api.py

# 清理
clean:
	@echo "清理临时文件..."
	find . -type d -name "__pycache__" -exec rm -rf {} +
	find . -type f -name "*.pyc" -delete
	find . -type f -name "*.pyo" -delete
	find . -type f -name "*.log" -delete
	rm -rf .pytest_cache .mypy_cache .coverage htmlcov
	@echo "清理完成!"

# Docker操作
docker-build:
	@echo "构建Docker镜像..."
	docker build -t lesson-plan-generator:latest .

docker-run:
	@echo "启动Docker容器..."
	docker-compose up -d
	@echo "容器启动完成! 访问 http://localhost:8000"

docker-stop:
	@echo "停止Docker容器..."
	docker-compose down

docker-logs:
	@echo "查看Docker日志..."
	docker-compose logs -f api

# 代码质量
format:
	@echo "格式化代码..."
	black lesson_plan_generator.py app.py test_api.py

lint:
	@echo "运行代码风格检查..."
	flake8 lesson_plan_generator.py app.py --max-line-length=88 --extend-ignore=E203,W503

type-check:
	@echo "运行类型检查..."
	mypy lesson_plan_generator.py app.py --ignore-missing-imports

check: format lint type-check
	@echo "所有检查通过!"

# 查看环境变量示例
show-env:
	@echo "环境变量配置示例:"
	@cat .env.example
